ALTER TABLE purchase_orders DROP CONSTRAINT IF EXISTS ck_purchase_order_status;
ALTER TABLE purchase_orders ADD CONSTRAINT ck_purchase_order_status CHECK (status IN ('DRAFT','PENDING_SUPERVISOR_APPROVAL','SUPERVISOR_REJECTED','PENDING_SUPPLIER_APPROVAL','SUPPLIER_REJECTED','AWAITING_RECEPTION','PARTIALLY_RECEIVED','RECEIVED'));
ALTER TABLE purchase_order_history DROP CONSTRAINT IF EXISTS ck_purchase_order_history_to_status;
ALTER TABLE purchase_order_history ADD CONSTRAINT ck_purchase_order_history_to_status CHECK (to_status IN ('DRAFT','PENDING_SUPERVISOR_APPROVAL','SUPERVISOR_REJECTED','PENDING_SUPPLIER_APPROVAL','SUPPLIER_REJECTED','AWAITING_RECEPTION','PARTIALLY_RECEIVED','RECEIVED'));
ALTER TABLE purchase_order_history DROP CONSTRAINT IF EXISTS ck_purchase_order_history_from_status;
ALTER TABLE purchase_order_history ADD CONSTRAINT ck_purchase_order_history_from_status CHECK (from_status IS NULL OR from_status IN ('DRAFT','PENDING_SUPERVISOR_APPROVAL','SUPERVISOR_REJECTED','PENDING_SUPPLIER_APPROVAL','SUPPLIER_REJECTED','AWAITING_RECEPTION','PARTIALLY_RECEIVED','RECEIVED'));
CREATE SEQUENCE reception_number_seq START WITH 1 INCREMENT BY 1 NO CYCLE;
CREATE TABLE receptions (id UUID PRIMARY KEY, reception_number VARCHAR(30) NOT NULL UNIQUE, organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE RESTRICT, station_id UUID NOT NULL REFERENCES stations(id) ON DELETE RESTRICT, purchase_order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE RESTRICT, delivery_note_number VARCHAR(100), delivery_date TIMESTAMPTZ, general_observation VARCHAR(2000), status VARCHAR(40) NOT NULL, created_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, submitted_at TIMESTAMPTZ, supervisor_reviewed_by UUID REFERENCES users(id) ON DELETE RESTRICT, supervisor_reviewed_at TIMESTAMPTZ, supervisor_comment VARCHAR(1000), version BIGINT NOT NULL DEFAULT 0, CONSTRAINT ck_reception_status CHECK(status IN ('DRAFT','PENDING_SUPERVISOR_APPROVAL','RETURNED_FOR_CORRECTION','APPROVED','VALIDATED','CANCELLED')));
CREATE INDEX idx_reception_org_status ON receptions(organization_id,status); CREATE INDEX idx_reception_po ON receptions(purchase_order_id);
CREATE TABLE reception_items (id UUID PRIMARY KEY, reception_id UUID NOT NULL REFERENCES receptions(id) ON DELETE RESTRICT, purchase_order_item_id UUID NOT NULL REFERENCES purchase_order_items(id) ON DELETE RESTRICT, product_id UUID NOT NULL REFERENCES products(id) ON DELETE RESTRICT, ordered_quantity_snapshot NUMERIC(19,3) NOT NULL, previously_received_quantity NUMERIC(19,3) NOT NULL, backlog_before_reception NUMERIC(19,3) NOT NULL, received_quantity NUMERIC(19,3) NOT NULL, purchase_unit_price NUMERIC(19,4), currency VARCHAR(3), difference_quantity NUMERIC(19,3) NOT NULL, observation VARCHAR(2000), CONSTRAINT uk_reception_item_po_item UNIQUE(reception_id,purchase_order_item_id), CONSTRAINT ck_reception_item_received CHECK(received_quantity>0), CONSTRAINT ck_reception_item_price CHECK(purchase_unit_price IS NULL OR purchase_unit_price>0), CONSTRAINT ck_reception_item_snapshots CHECK(ordered_quantity_snapshot>=0 AND previously_received_quantity>=0 AND backlog_before_reception>=0));
CREATE INDEX idx_reception_items_reception ON reception_items(reception_id); CREATE INDEX idx_reception_items_po_item ON reception_items(purchase_order_item_id);
CREATE TABLE reception_tank_allocations (id UUID PRIMARY KEY, reception_item_id UUID NOT NULL REFERENCES reception_items(id) ON DELETE RESTRICT, tank_id UUID NOT NULL REFERENCES tanks(id) ON DELETE RESTRICT, quantity NUMERIC(19,3) NOT NULL, created_at TIMESTAMPTZ NOT NULL, CONSTRAINT ck_reception_allocation_quantity CHECK(quantity>0)); CREATE INDEX idx_reception_alloc_item ON reception_tank_allocations(reception_item_id);
CREATE TABLE reception_history (id UUID PRIMARY KEY, reception_id UUID NOT NULL REFERENCES receptions(id) ON DELETE RESTRICT, action VARCHAR(40) NOT NULL, old_status VARCHAR(40), new_status VARCHAR(40) NOT NULL, performed_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, performed_at TIMESTAMPTZ NOT NULL, comment VARCHAR(1000), CONSTRAINT ck_reception_history_action CHECK(action IN ('RECEPTION_CREATED','RECEPTION_UPDATED','RECEPTION_SUBMITTED','SUPERVISOR_APPROVED','RETURNED_FOR_CORRECTION','RECEPTION_CANCELLED','RECEPTION_VALIDATED'))); CREATE INDEX idx_reception_history_timeline ON reception_history(reception_id,performed_at,id);
INSERT INTO permissions(id,code,name,description,module,system_permission,active,created_at,updated_at) SELECT gen_random_uuid(),v.code,v.name,v.description,'RECEPTION',TRUE,TRUE,now(),now() FROM (VALUES ('reception:view','Consulter les réceptions','Consulter les réceptions autorisées'),('reception:create','Créer une réception','Créer une réception'),('reception:update','Modifier une réception','Modifier une réception modifiable'),('reception:submit','Soumettre une réception','Soumettre une réception'),('reception:approve','Valider une réception','Valider une surlivraison'),('reception:return','Retourner une réception','Retourner une réception pour correction'),('reception:cancel','Annuler une réception','Annuler une réception')) AS v(code,name,description) WHERE NOT EXISTS(SELECT 1 FROM permissions p WHERE p.code=v.code);
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON (r.code='MANAGER' AND p.code IN ('reception:view','reception:create','reception:update','reception:submit')) OR (r.code='SUPERVISOR' AND p.code IN ('reception:view','reception:approve','reception:return','reception:cancel')) OR r.code='SUPER_ADMIN' WHERE NOT EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=r.id AND rp.permission_id=p.id);
